namespace RonSijm.FluidHumidifier.Factories.Bedrock;

public class DataAutomationProjectFactory(string resourceName = null, Action<Humidifier.Bedrock.DataAutomationProject> factoryAction = null) : ResourceFactory<Humidifier.Bedrock.DataAutomationProject>(resourceName)
{

    internal InnerDataAutomationProjectStandardOutputConfigurationFactory StandardOutputConfigurationFactory { get; set; }

    internal InnerDataAutomationProjectOverrideConfigurationFactory OverrideConfigurationFactory { get; set; }

    internal InnerDataAutomationProjectCustomOutputConfigurationFactory CustomOutputConfigurationFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProject Create()
    {
        var dataAutomationProjectResult = CreateDataAutomationProject();
        factoryAction?.Invoke(dataAutomationProjectResult);

        return dataAutomationProjectResult;
    }

    private Humidifier.Bedrock.DataAutomationProject CreateDataAutomationProject()
    {
        var dataAutomationProjectResult = new Humidifier.Bedrock.DataAutomationProject
        {
            GivenName = InputResourceName,
        };

        return dataAutomationProjectResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProject result)
    {
        base.CreateChildren(result);

        result.StandardOutputConfiguration ??= StandardOutputConfigurationFactory?.Build();
        result.OverrideConfiguration ??= OverrideConfigurationFactory?.Build();
        result.CustomOutputConfiguration ??= CustomOutputConfigurationFactory?.Build();
    }

} // End Of Class

